const state={user:null,csrf:'',page:'dashboard',installPrompt:null,scanStream:null,scanTimer:null,aiBusy:false,mobileOffline:false};
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const today=()=>new Date().toISOString().slice(0,10);
const isLoopbackHost=()=>['127.0.0.1','localhost','::1','[::1]'].includes(location.hostname);
const isStandalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const cacheMobileProfile=p=>{try{if(p&&typeof p==='object')localStorage.setItem('ff_mobile_profile',JSON.stringify(p))}catch{}};
const getMobileProfile=()=>{try{return JSON.parse(localStorage.getItem('ff_mobile_profile')||'null')||{name:'Athlete',goal:'General fitness',experience:'beginner',daysPerWeek:3,equipment:'Bodyweight only'}}catch{return{name:'Athlete',goal:'General fitness',experience:'beginner',daysPerWeek:3,equipment:'Bodyweight only'}}};
async function prepareServiceWorker(){if(!('serviceWorker'in navigator))return;if(isLoopbackHost()){const regs=await navigator.serviceWorker.getRegistrations().catch(()=>[]);await Promise.all(regs.map(r=>r.unregister()));if('caches'in window){const keys=await caches.keys().catch(()=>[]);await Promise.all(keys.filter(k=>k.startsWith('formforge-')).map(k=>caches.delete(k)))}}else{navigator.serviceWorker.register('/sw.js?v=180').then(r=>r.update()).catch(()=>{})}}
async function retryAPI(path,opt={},attempts=8){let last;for(let i=0;i<attempts;i++){try{return await api(path,opt)}catch(e){last=e;if(i<attempts-1)await new Promise(r=>setTimeout(r,350+i*180))}}throw last}
function localCoachReply(message,profile=getMobileProfile()){
  const q=String(message||'').toLowerCase(),pack=getMobileCoachPack(),ids=new Set((pack.preferences?.influences||[]).map(x=>x.profileId));
  const days=Math.max(2,Math.min(6,+profile.daysPerWeek||3));const eq=String(profile.equipment||'Bodyweight only').toLowerCase();
  const push=eq.includes('body')?'Push-ups':eq.includes('dumb')?'Dumbbell bench press':'Bench press';
  const pull=eq.includes('body')?'Backpack rows or table rows':eq.includes('dumb')?'One-arm dumbbell rows':'Cable or barbell rows';
  const squat=eq.includes('body')?'Tempo squats':eq.includes('dumb')?'Goblet squats':'Back squats';
  const hinge=eq.includes('body')?'Single-leg hip hinges':eq.includes('dumb')?'Dumbbell Romanian deadlifts':'Romanian deadlifts';
  const finish=text=>decorateLocalCoachReply(text);
  if(/pain|injur|chest pain|faint|numb/.test(q))return 'Stop any movement that causes sharp, worsening, or joint pain. I cannot diagnose an injury. Use only pain-free activity, and seek medical care for chest pain, fainting, major swelling, weakness, numbness, severe shortness of breath, or an acute injury.';
  if(/quote/.test(q)){const src=(pack.sources||[]).find(x=>x.quoteVerified&&x.quote);return src?`Verified quote:\n\n“${src.quote}”\n\nSource: ${src.sourceUrl}`:'I do not have a verified quotation in the downloaded coach pack. I will not invent or misattribute one.'}
  if(/who are my coaches|coach blend|coaching team|influences/.test(q))return `Your downloaded coaching blend is ${pack.blend||'FormForge Balanced'}. I use broad training principles and communication traits, but I remain FormForge Coach and do not impersonate or claim endorsement from any creator.`;
  if(/protein|calorie|nutrition|eat/.test(q))return finish(`Offline nutrition guide for ${profile.goal||'your goal'}: build each meal around a protein source, vegetables or fruit, and a measured carb or fat source. Aim for roughly 0.7–1.0 g of protein per pound of goal body weight, adjust calories gradually, and judge changes from 2–3 weeks of body-weight averages rather than one day.`);
  if(/progress|stronger|plateau|increase/.test(q))return finish('Use double progression: stay in the prescribed rep range, add reps until every set reaches the top with clean technique, then add the smallest practical amount of weight and return to the bottom of the range. If performance drops for two weeks, reduce total sets by about 25% for one week.');
  if(/light|recovery|tired|deload/.test(q))return finish(`Recovery week: train ${Math.max(2,days-1)} days, keep 3–4 reps in reserve, remove one set from every exercise, avoid failure, and use 60–75% of your normal working weights. Keep easy walking and normal protein intake.`);
  const effort=ids.has('ronnie-coleman')?' On the final safe isolation movement, one controlled high-effort set is optional—never at the cost of technique.':'';
  const pump=ids.has('arnold-schwarzenegger')?' Finish with 2 controlled pump sets for the target muscle and focus on the contraction.':'';
  const fatigue=ids.has('mike-israetel')||ids.has('jeff-nippard')?' Keep most working sets around 1–3 reps in reserve and add volume only when performance and recovery support it.':'';
  const consistency=ids.has('noel-deyzel')?' Your job is to complete the basics consistently, not chase a perfect session.':'';
  const accountability=ids.has('david-goggins')?' Put the sessions on the calendar now and record whether you completed them.':'';
  const templates=[
    `Day 1 — Full body A\n• ${squat}: 4×6–10, rest 2 min\n• ${push}: 4×6–10, rest 2 min\n• ${pull}: 4×8–12, rest 90 sec\n• Plank: 3×30–60 sec`,
    `Day 2 — Full body B\n• ${hinge}: 4×6–10, rest 2 min\n• Overhead press variation: 3×8–12, rest 90 sec\n• Split squats: 3×8–12 each side\n• Curl + triceps extension: 3×10–15 each`,
    `Day 3 — Strength and conditioning\n• ${squat}: 3×8\n• ${push}: 3×8–12\n• ${pull}: 3×10–12\n• Calf raises: 4×12–20\n• Easy intervals: 8 rounds of 30 sec brisk / 60 sec easy`
  ];
  const out=[];for(let i=0;i<days;i++)out.push(templates[i%templates.length].replace(/Day \d+/,`Day ${i+1}`));
  return finish(`${profile.name?profile.name.split(' ')[0]+', ':''}here is a ${days}-day offline plan for ${profile.goal||'general fitness'} using ${profile.equipment||'available equipment'}.\n\n${out.join('\n\n')}\n\nKeep 1–3 good reps in reserve on most sets. Add reps first, then weight.${effort}${pump}${fatigue}${consistency}${accountability}`);
}
function offlineChatMessages(){try{return JSON.parse(localStorage.getItem('ff_mobile_offline_chat')||'[]')}catch{return[]}}
function saveOfflineChat(messages){try{localStorage.setItem('ff_mobile_offline_chat',JSON.stringify(messages.slice(-60)))}catch{}}
function showOfflineCoach(){state.mobileOffline=true;const profile=getMobileProfile();const messages=offlineChatMessages();document.body.innerHTML=`<main class="offline-shell"><section class="offline-card"><div class="offline-head"><div><p class="eyebrow">PHONE OFFLINE MODE</p><h1>FormForge Coach</h1><p class="muted">This private fallback runs in your phone browser. Shared records sync only after the Windows server reconnects.</p></div><button class="outline-btn" id="offline-retry">Reconnect</button></div><div id="offline-history" class="chat-history">${messages.length?messages.map(coachBubble).join(''):'<div class="empty">Ask for a workout, progression advice, recovery week, or nutrition target.</div>'}</div><form id="offline-form" class="coach-compose"><select class="select" disabled><option>Offline on phone</option></select><textarea class="textarea" name="message" placeholder="Build me a workout" required></textarea><button class="primary-btn">Send</button></form><button class="ghost-btn" id="offline-clear">Clear offline chat</button></section></main>`;const hist=$('#offline-history');hist.scrollTop=hist.scrollHeight;$('#offline-retry').onclick=()=>location.reload();$('#offline-clear').onclick=()=>{saveOfflineChat([]);showOfflineCoach()};$('#offline-form').onsubmit=e=>{e.preventDefault();const msg=String(new FormData(e.currentTarget).get('message')||'').trim();if(!msg)return;const list=offlineChatMessages();list.push({role:'user',content:msg,mode:'phone-offline'});list.push({role:'assistant',content:localCoachReply(msg,profile),mode:'phone-offline'});saveOfflineChat(list);showOfflineCoach()}}
function renderStartupFailure(err){const desktop=isLoopbackHost();document.body.innerHTML=`<main class="auth-shell"><section class="auth-card"><div class="brand-mark">FF</div><p class="eyebrow">CONNECTION REPAIR</p><h1>FormForge could not connect</h1><p>${esc(err?.message||'Failed to fetch')}</p><div class="notice danger">${desktop?'A browser-installed FormForge shortcut cannot start the local server by itself. Use the real FormForge desktop shortcut or the button below.':'The Windows FormForge server is not reachable. Confirm the PC is running FormForge and both devices are on the same private Wi-Fi.'}</div><div class="stack" style="margin-top:14px"><button class="primary-btn" id="startup-retry">Retry connection</button>${desktop?'<a class="outline-btn" id="startup-launch" href="formforge://start" style="text-align:center;text-decoration:none">Start FormForge server</a>':''}<button class="outline-btn" id="startup-offline">Use offline AI coach</button></div><p class="muted">No stored customer data is deleted by this screen.</p></section></main>`;$('#startup-retry').onclick=()=>location.reload();$('#startup-offline').onclick=showOfflineCoach}
function toast(msg,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=msg;$('#toast').append(el);setTimeout(()=>el.remove(),4000)}
async function api(path,opt={}){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),opt.timeout||30000);const o={...opt,signal:opt.signal||controller.signal,headers:{...(opt.headers||{})}};if(o.body&&!(o.body instanceof FormData)&&typeof o.body!=='string'){o.headers['Content-Type']='application/json';o.body=JSON.stringify(o.body)};if(o.method&&o.method!=='GET'&&state.csrf)o.headers['X-CSRF-Token']=state.csrf;try{const res=await fetch(path,o);let data=null;const ct=res.headers.get('content-type')||'';if(ct.includes('json')){try{data=await res.json()}catch{}}else data=await res.text();if(res.status===401){showAuth(false);throw new Error(data?.message||'Please sign in.')};if(!res.ok)throw new Error(data?.message||`Request failed (${res.status})`);if(path==='/api/profile')cacheMobileProfile(data);return data}catch(err){if(err.name==='AbortError')throw new Error('The local service took too long to respond. Restart FormForge and try again.');if(err instanceof TypeError)throw new Error('Could not reach the local FormForge service. Restart the app; your data is stored separately and will not be erased.');throw err}finally{clearTimeout(timeout)}}
function field(label,name,value='',type='text',attrs=''){return `<label class="field-wrap"><span>${esc(label)}</span><input class="field" name="${esc(name)}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function selectField(label,name,value,options){return `<label class="field-wrap"><span>${esc(label)}</span><select class="select" name="${esc(name)}">${options.map(x=>{const v=typeof x==='string'?x:x.value,l=typeof x==='string'?x:x.label;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`}
function modal(title,body,kicker=''){ $('#modal-title').textContent=title;$('#modal-kicker').textContent=kicker;$('#modal-body').innerHTML=body;$('#modal').showModal() }
function closeModal(){stopBarcodeScanner();if($('#modal').open)$('#modal').close()}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();if(isLoopbackHost())return;state.installPrompt=e;$('#install-btn').classList.remove('hidden')});
$('#install-btn').addEventListener('click',async()=>{if(state.installPrompt){state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null;$('#install-btn').classList.add('hidden')}});
$('#logout-btn').addEventListener('click',async()=>{try{await api('/api/auth/logout',{method:'POST'});}catch{}state.user=null;state.csrf='';showAuth(false)});$('#refresh-btn').addEventListener('click',()=>renderPage());
$('#recovery-toggle').addEventListener('click',()=>{$('#recovery-panel').classList.toggle('hidden');renderRecovery()});

async function boot(){await prepareServiceWorker();const status=await retryAPI('/api/system/status',{timeout:2500},6);try{const sess=await api('/api/auth/session',{timeout:5000});state.user=sess.user;state.csrf=sess.csrf;showApp()}catch{showAuth(status.setupRequired,status.setupTokenRequired)}}
function showAuth(setup,setupTokenRequired=false){$('#app-shell').classList.add('hidden');$('#auth-shell').classList.remove('hidden');$('#recovery-panel').classList.add('hidden');$('#auth-title').textContent=setup?'Create your secure workspace':'Welcome back';$('#auth-copy').textContent=setup?'Create the first administrator account. Hosted deployments require the private setup token from Render.':'Sign in to your FormForge workspace.';$('#recovery-toggle').classList.toggle('hidden',setup);$('#auth-form').innerHTML=setup?setupForm(setupTokenRequired):loginForm();$('#auth-form').onsubmit=setup?submitSetup:submitLogin}
function loginForm(){return `${field('Email','email','','email','required autocomplete="username"')}${field('Password','password','','password','required autocomplete="current-password"')}${field('Authenticator or recovery code','totp','','text','autocomplete="one-time-code" inputmode="numeric" placeholder="Only required when admin 2FA is enabled"')}<button class="primary-btn" type="submit">Sign in</button>`}
function setupForm(setupTokenRequired=false){return `${setupTokenRequired?field('Hosted setup token','setupToken','','password','required autocomplete="off" placeholder="Copy from Render environment variables"'):''}${field('Name','name','','text','required')}${field('Email','email','','email','required')}${field('Password','password','','password','required minlength="12" placeholder="12+ chars, uppercase, lowercase, number"')}<div class="form-grid">${field('Age','age','25','number','min="13" max="120" required')}${selectField('Gender','gender','male',['male','female','other','prefer not to say'])}${field('Height (cm)','heightCm','175','number','min="100" max="250" required')}${field('Weight (kg)','weightKg','80','number','min="25" max="400" step="0.1" required')}${selectField('Primary goal','goal','Build muscle',['Build muscle','Lose fat','Improve endurance','Increase strength','General fitness'])}${selectField('Experience','experience','beginner',[{value:'beginner',label:'Beginner'},{value:'intermediate',label:'Intermediate'},{value:'advanced',label:'Advanced'}])}${selectField('Days per week','daysPerWeek','3',['2','3','4','5','6'])}${selectField('Equipment','equipment','Full gym',['Full gym','Home gym','Dumbbells only','Bodyweight only','Resistance bands'])}</div>${coachSetupFields()}<button class="primary-btn" type="submit">Create FormForge workspace</button>`}
async function submitLogin(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));try{const d=await api('/api/auth/login',{method:'POST',body:f});state.user=d.user;state.csrf=d.csrf;showApp()}catch(err){toast(err.message,true)}}
async function submitSetup(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));const body={name:f.name,email:f.email,password:f.password,setupToken:f.setupToken||'',profile:{name:f.name,age:+f.age,gender:f.gender,heightCm:+f.heightCm,weightKg:+f.weightKg,goal:f.goal,experience:f.experience,daysPerWeek:+f.daysPerWeek,equipment:f.equipment},coachingPreferences:selectedSetupCoachPreferences(e.currentTarget)};try{const d=await api('/api/auth/setup',{method:'POST',body});state.user=d.user;state.csrf=d.csrf;modal('Save your recovery key',`<div class="notice danger"><strong>This is shown once during setup.</strong> Save it somewhere offline. It decrypts backups and can reset an administrator password.</div><textarea class="textarea" readonly>${esc(d.recoveryKey)}</textarea><div class="button-row"><button class="primary-btn" id="download-first-key">Download key</button><button class="outline-btn" id="continue-app">Continue</button></div>`,'SECURITY');$('#download-first-key').onclick=()=>downloadText('FormForge-Recovery-Key.txt',`FORMFORGE RECOVERY KEY\n\n${d.recoveryKey}\n`);$('#continue-app').onclick=()=>{closeModal();showApp()}}catch(err){toast(err.message,true)}}
function renderRecovery(){if($('#recovery-panel').classList.contains('hidden'))return;$('#recovery-panel').innerHTML=`<div class="stack" style="margin-top:16px">${field('Administrator email','recoveryEmail','','email')}${field('Recovery key','recoveryKey','','text')}${field('New password','newPassword','','password','minlength="12"')}<button class="outline-btn" id="recover-btn">Reset administrator password</button></div>`;$('#recover-btn').onclick=async()=>{const panel=$('#recovery-panel');const body={email:$('[name=recoveryEmail]',panel).value,recoveryKey:$('[name=recoveryKey]',panel).value,newPassword:$('[name=newPassword]',panel).value};try{await api('/api/auth/recover',{method:'POST',body});toast('Password reset. You can sign in now.');panel.classList.add('hidden')}catch(err){toast(err.message,true)}}}
function showApp(){closeModal();$('#auth-shell').classList.add('hidden');$('#app-shell').classList.remove('hidden');$('#user-chip').textContent=`${state.user.name} · ${state.user.role}`;buildNav();state.page='dashboard';renderPage()}
const navItems=[['dashboard','⌂','Dashboard'],['team','◎','Coaching Team'],['coach','✦','AI Coach'],['workouts','⚡','Workouts'],['nutrition','🥗','Nutrition'],['health','♥','Health + Plans'],['progress','↗','Progress'],['habits','✓','Habits'],['social','♟','Community'],['checkin','▣','Check-In'],['mobile','▤','Mobile'],['security','⌾','Security'],['admin','⚙','Admin'],['settings','☰','Settings']];
function buildNav(){const items=navItems.filter(x=>x[0]!=='admin'||state.user.role==='admin');const html=items.map(([id,icon,label])=>`<button class="nav-btn ${state.page===id?'active':''}" data-page="${id}"><span>${icon}</span><span>${label}</span></button>`).join('');$('#desktop-nav').innerHTML=html;$('#mobile-nav').innerHTML=html;$$('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;buildNav();renderPage()})}
async function renderPage(){buildNav();const meta={dashboard:['OVERVIEW','Dashboard'],team:['INFLUENCE BLEND','Coaching Team'],coach:['LOCAL + ONLINE','AI Coach'],workouts:['TRAINING','Workouts'],nutrition:['FUEL','Nutrition'],health:['WEARABLES + RECOVERY','Health + Plans'],progress:['TRENDS','Progress'],habits:['CONSISTENCY','Habits'],social:['HOUSEHOLD','Community'],checkin:['WEEKLY REVIEW','Check-In'],mobile:['PHONE + TABLET','Mobile App'],security:['PRIVACY + ACCESS','Security'],admin:['ACCESS & AUDIT','Administration'],settings:['SYSTEM','Settings']}[state.page]||['OVERVIEW','Dashboard'];$('#page-kicker').textContent=meta[0];$('#page-title').textContent=meta[1];$('#content').innerHTML='<div class="empty">Loading…</div>';try{await ({dashboard:renderDashboard,team:renderCoachingTeam,coach:renderCoach,workouts:renderWorkouts,nutrition:renderNutrition,health:renderHealth,progress:renderProgress,habits:renderHabits,social:renderSocial,checkin:renderCheckin,mobile:renderMobile,security:renderSecurity,admin:renderAdmin,settings:renderSettings}[state.page]||renderDashboard)()}catch(err){console.error(err);$('#content').innerHTML=`<div class="notice danger"><strong>Could not load this screen.</strong><br>${esc(err.message)}<div class="button-row" style="margin-top:12px"><button class="primary-btn" id="retry-screen">Retry</button><button class="outline-btn" id="go-dashboard">Dashboard</button></div></div>`;$('#retry-screen').onclick=renderPage;$('#go-dashboard').onclick=()=>{state.page='dashboard';renderPage()}}}
function progressBar(v,max){const pct=Math.max(0,Math.min(100,max?Math.round(v/max*100):0));return `<div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><small class="muted">${Math.round(v)} / ${Math.round(max||0)} (${pct}%)</small>`}
async function renderDashboard(){const d=await api('/api/dashboard');const t=d.today,p=d.profile||{};const hPct=t.habitTotal?Math.round(t.habitDone/t.habitTotal*100):0;$('#content').innerHTML=`<div class="grid grid-4"><div class="card stat"><div><span class="muted">Calories today</span><strong>${Math.round(t.calories)}</strong><small class="muted">of ${p.calorieGoal||0}</small></div><span class="stat-icon">🔥</span></div><div class="card stat"><div><span class="muted">Workouts</span><strong>${d.weeklyWorkouts}</strong><small class="muted">this week</small></div><span class="stat-icon">💪</span></div><div class="card stat"><div><span class="muted">Habits</span><strong>${hPct}%</strong><small class="muted">done today</small></div><span class="stat-icon">✓</span></div><div class="card stat"><div><span class="muted">Streak</span><strong>${d.streak}</strong><small class="muted">active days</small></div><span class="stat-icon">⚡</span></div></div><div class="grid grid-2" style="margin-top:16px"><div class="card"><div class="section-head" style="margin:0 0 12px"><h2>Week at a glance</h2><button class="outline-btn" data-go="workouts">Edit plan</button></div><div class="week-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=>`<div class="day-card"><strong>${day}</strong><span>${esc(d.plan?.[day]||'Rest')}</span></div>`).join('')}</div></div><div class="card"><h2>Nutrition targets</h2><div class="stack"><div><div class="list-row"><span>Calories</span><strong>${Math.round(t.calories)} kcal</strong></div>${progressBar(t.calories,p.calorieGoal)}</div><div><div class="list-row"><span>Protein</span><strong>${Math.round(t.protein)} g</strong></div>${progressBar(t.protein,p.proteinGoal)}</div></div></div></div><div class="section-head"><h2>Recent workouts</h2></div>${d.recentWorkouts?.length?`<div class="list">${d.recentWorkouts.map(x=>`<div class="list-row"><div><strong>${esc(x.workoutName)}</strong><small>${esc(x.date)} · ${x.duration||0} min</small></div><span class="pill">Completed</span></div>`).join('')}</div>`:'<div class="empty">No workouts logged yet.</div>'}`;$$('[data-go]').forEach(b=>b.onclick=()=>{state.page=b.dataset.go;renderPage()})}

function coachBubble(m){const role=m.role==='user'?'You':'Coach';const mode=m.role==='assistant'?`<span class="pill">${esc(m.mode||'offline')}</span>`:'';const grounding=(m.grounding||[]).map(g=>`<span class="pill ${g.kind==='source'?'online-ready':'muted-pill'}">${esc(g.label)}</span>`).join('');const del=m.id?`<button class="ghost-btn delete-chat" data-id="${esc(m.id)}" title="Delete message">×</button>`:'';return `<article class="chat-bubble ${m.role==='user'?'chat-user':'chat-assistant'}"><div class="chat-meta"><strong>${role}</strong>${mode}${grounding}${del}</div><div class="chat-copy">${esc(m.content).replace(/\n/g,'<br>')}</div></article>`}
async function renderCoach(){const [history,status,profile,pack]=await Promise.all([api('/api/ai/history?limit=80'),api('/api/ai/status'),api('/api/profile'),api('/api/coaching/pack')]);cacheMobileProfile(profile);cacheCoachPack(pack);const online=status.apiKeyConfigured;$('#content').innerHTML=`<div class="coach-layout"><section class="card coach-main"><div class="section-head" style="margin-top:0"><div><p class="eyebrow">PRIVATE FITNESS COACH</p><h2>Talk to FormForge</h2><p class="muted">Offline works immediately. Your selected coaching blend shapes both offline and online answers without impersonating a creator.</p><div class="notice mini"><strong>Current blend:</strong> ${esc(pack.blend||'FormForge Balanced')} · <button class="link-button" type="button" id="edit-coach-team">Edit team</button></div></div><div class="status-stack"><span class="pill">Offline ready</span><span class="pill ${online?'online-ready':'muted-pill'}">${online?'Online configured':'Online not configured'}</span></div></div><div class="quick-prompts"><button class="tab-chip coach-prompt">Build me a ${profile.daysPerWeek||3}-day workout</button><button class="tab-chip coach-prompt">Summarize my progress</button><button class="tab-chip coach-prompt">How should I progress my lifts?</button><button class="tab-chip coach-prompt">Make this week lighter</button></div><div id="chat-history" class="chat-history">${history.length?history.map(coachBubble).join(''):`<div class="empty">Ask for a workout, substitution, progression rule, recovery adjustment, nutrition target, or progress summary.</div>`}</div><form id="coach-form" class="coach-compose"><select class="select" name="mode" aria-label="AI mode"><option value="auto" ${status.mode==='auto'?'selected':''}>Auto</option><option value="offline" ${status.mode==='offline'?'selected':''}>Offline</option><option value="online" ${status.mode==='online'?'selected':''}>Online</option></select><textarea class="textarea" name="message" placeholder="Example: Give me a 4-day muscle-building plan with dumbbells" required></textarea><button class="primary-btn" id="send-coach">Send</button></form><div class="button-row" style="margin-top:10px"><button class="ghost-btn" id="clear-chat">Clear conversation</button></div></section>${state.user.role==='admin'?`<aside class="card coach-settings"><p class="eyebrow">ONLINE MODE</p><h2>AI connection</h2><form id="ai-settings-form" class="stack">${selectField('Default mode','mode',status.mode,[{value:'auto',label:'Auto — online with offline fallback'},{value:'offline',label:'Offline only'},{value:'online',label:'Online only'}])}${field('Service URL','baseUrl',status.baseUrl,'url','required')}${field('Model','model',status.model,'text','required')}${field(status.apiKeyConfigured?'Replace API key':'API key','apiKey','','password',status.apiKeyConfigured?'placeholder="Saved key is encrypted; leave blank to keep it"':'required placeholder="Stored encrypted on this PC"')}<label class="field-wrap"><span><input type="checkbox" name="clearKey"> Remove saved API key</span></label><button class="primary-btn">Save AI settings</button><button type="button" class="outline-btn" id="test-ai">Test online connection</button><div class="notice">The key is sent only from the local backend to the configured AI service. It is never returned to the browser or placed in exported user data.</div></form></aside>`:''}</div>`;$('#edit-coach-team').onclick=()=>{state.page='team';renderPage()};const historyEl=$('#chat-history');historyEl.scrollTop=historyEl.scrollHeight;$$('.coach-prompt').forEach(b=>b.onclick=()=>{$('#coach-form textarea').value=b.textContent;$('#coach-form textarea').focus()});$('#coach-form').onsubmit=async e=>{e.preventDefault();if(state.aiBusy)return;const f=Object.fromEntries(new FormData(e.currentTarget));const message=String(f.message||'').trim();if(!message)return;state.aiBusy=true;$('#send-coach').disabled=true;historyEl.insertAdjacentHTML('beforeend',coachBubble({role:'user',content:message}));historyEl.insertAdjacentHTML('beforeend','<div id="coach-thinking" class="chat-bubble chat-assistant"><div class="chat-copy">Thinking…</div></div>');historyEl.scrollTop=historyEl.scrollHeight;e.currentTarget.elements.message.value='';try{const result=await api('/api/ai/chat',{method:'POST',body:{message,mode:f.mode},timeout:45000});$('#coach-thinking')?.remove();historyEl.insertAdjacentHTML('beforeend',coachBubble({role:'assistant',content:result.reply,mode:result.mode,grounding:result.grounding||[]}));if(result.fallbackReason)toast(result.fallbackReason)}catch(err){$('#coach-thinking')?.remove();const reply=localCoachReply(message,profile);const local=offlineChatMessages();local.push({role:'user',content:message,mode:'phone-offline'},{role:'assistant',content:reply,mode:'phone-offline'});saveOfflineChat(local);historyEl.insertAdjacentHTML('beforeend',coachBubble({role:'assistant',content:reply,mode:'phone-offline'}));toast('Server connection failed, so the phone offline coach answered.',true)}finally{state.aiBusy=false;$('#send-coach').disabled=false;historyEl.scrollTop=historyEl.scrollHeight}};$('#clear-chat').onclick=async()=>{if(!confirm('Clear your AI conversation history?'))return;await api('/api/ai/history',{method:'DELETE'});renderCoach()};if(state.user.role==='admin'){const form=$('#ai-settings-form');form.onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/ai/settings',{method:'PUT',body:{mode:f.mode,baseUrl:f.baseUrl,model:f.model,apiKey:f.apiKey||'',clearKey:f.clearKey==='on'}});toast('AI settings saved.');renderCoach()}catch(err){toast(err.message,true)}};$('#test-ai').onclick=async()=>{const f=Object.fromEntries(new FormData(form));$('#test-ai').disabled=true;try{const r=await api('/api/ai/test',{method:'POST',body:{baseUrl:f.baseUrl,model:f.model,apiKey:f.apiKey||''},timeout:45000});toast(r.reply||'Online AI connected.')}catch(err){toast(err.message,true)}finally{$('#test-ai').disabled=false}}}}

async function renderWorkouts(){const [workouts,plan,logs]=await Promise.all([api('/api/workouts'),api('/api/plan'),api('/api/workout-logs')]);$('#content').innerHTML=`<div class="section-head" style="margin-top:0"><h2>Weekly plan</h2><div class="button-row"><button class="primary-btn" id="save-plan">Save plan</button><button class="outline-btn" id="new-workout">Create custom</button></div></div><div class="card"><div class="form-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=>selectField(day,day,plan[day]||'',[{value:'',label:'Rest day'},...workouts.map(x=>({value:x.name,label:x.name}))])).join('')}</div></div><div class="section-head"><h2>Workout library</h2></div><div class="grid grid-2">${workouts.map(x=>`<article class="card"><div class="section-head" style="margin:0"><div><span class="pill">${esc(x.category)}</span><h3>${esc(x.name)}</h3><small class="muted">${x.duration||0} min · ${x.builtIn?'Built-in':'Custom'}</small></div></div>${x.why?`<p class="muted">${esc(x.why)}</p>`:''}<details><summary>Exercises (${x.exercises.length})</summary>${x.exercises.map(e=>`<div class="exercise"><strong>${esc(e.name)}</strong><p>${e.sets} sets × ${esc(e.reps)} · Rest ${esc(e.rest)}</p>${e.why?`<p>Why: ${esc(e.why)}</p>`:''}</div>`).join('')}</details><div class="button-row" style="margin-top:12px"><button class="primary-btn log-workout" data-id="${x.id}" data-name="${esc(x.name)}" data-duration="${x.duration||0}">Log today</button>${!x.builtIn?`<button class="danger-btn delete-workout" data-id="${x.id}">Delete</button>`:''}</div></article>`).join('')}</div><div class="section-head"><h2>Workout history</h2></div>${logs.length?`<div class="list">${logs.slice(0,20).map(x=>`<div class="list-row"><div><strong>${esc(x.workoutName)}</strong><small>${x.date} · ${x.duration||0} min ${x.notes?'· '+esc(x.notes):''}</small></div><button class="ghost-btn delete-log" data-id="${x.id}">Delete</button></div>`).join('')}</div>`:'<div class="empty">No workout history yet.</div>'}`;$('#save-plan').onclick=async()=>{const form=$('.card .form-grid');const vals={};['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].forEach(d=>vals[d]=$(`[name="${d}"]`).value);try{await api('/api/plan',{method:'PUT',body:vals});toast('Weekly plan saved.')}catch(e){toast(e.message,true)}};$('#new-workout').onclick=openWorkoutModal;$$('.log-workout').forEach(b=>b.onclick=()=>openWorkoutLogModal(workouts.find(x=>x.id===b.dataset.id)||{id:b.dataset.id,name:b.dataset.name,duration:+b.dataset.duration,exercises:[]}));$$('.delete-workout').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this custom workout?'))return;try{await api('/api/workouts/'+b.dataset.id,{method:'DELETE'});renderWorkouts()}catch(e){toast(e.message,true)}});$$('.delete-log').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this workout log?'))return;await api('/api/workout-logs/'+b.dataset.id,{method:'DELETE'});renderWorkouts()})}
function openWorkoutModal(){modal('Create custom workout',`<form id="custom-workout-form" class="stack">${field('Workout name','name','','text','required')}${selectField('Category','category','Strength',['Strength','Cardio','Mobility','Custom'])}${field('Duration (minutes)','duration','45','number','min="1"')}<label class="field-wrap"><span>Exercises — one per line: Name | sets | reps | rest</span><textarea class="textarea" name="exercises" placeholder="Bench Press | 4 | 6-8 | 2min" required></textarea></label><button class="primary-btn">Create workout</button></form>`,'CUSTOM');$('#custom-workout-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));const exercises=f.exercises.split('\n').filter(Boolean).map(line=>{const [name,sets,reps,rest]=line.split('|').map(x=>x.trim());return{name,sets:+sets||1,reps:reps||'10',rest:rest||'60s'}});try{await api('/api/workouts',{method:'POST',body:{name:f.name,category:f.category,duration:+f.duration,exercises}});closeModal();toast('Custom workout created.');renderWorkouts()}catch(err){toast(err.message,true)}}}

async function renderNutrition(){const date=today();const [entries,dash]=await Promise.all([api('/api/nutrition?date='+date),api('/api/dashboard')]);const p=dash.profile||{};const totals=entries.reduce((a,x)=>({calories:a.calories+x.calories,protein:a.protein+x.protein,carbs:a.carbs+x.carbs,fat:a.fat+x.fat}),{calories:0,protein:0,carbs:0,fat:0});$('#content').innerHTML=`<div class="grid grid-4"><div class="card"><strong>${Math.round(totals.calories)}</strong><p class="muted">Calories</p>${progressBar(totals.calories,p.calorieGoal)}</div><div class="card"><strong>${Math.round(totals.protein)}g</strong><p class="muted">Protein</p>${progressBar(totals.protein,p.proteinGoal)}</div><div class="card"><strong>${Math.round(totals.carbs)}g</strong><p class="muted">Carbs</p>${progressBar(totals.carbs,p.carbGoal)}</div><div class="card"><strong>${Math.round(totals.fat)}g</strong><p class="muted">Fat</p>${progressBar(totals.fat,p.fatGoal)}</div></div><div class="section-head"><h2>Today's food</h2><div class="button-row"><button class="outline-btn" id="food-search-btn">Food library</button><button class="primary-btn" id="add-food">Add food</button></div></div>${entries.length?`<div class="list">${entries.map(x=>`<div class="list-row"><div><strong>${esc(x.name)}</strong><small>${esc(x.serving||'')} · ${Math.round(x.protein)}g P · ${Math.round(x.carbs)}g C · ${Math.round(x.fat)}g F</small></div><div><strong>${Math.round(x.calories)} kcal</strong><button class="ghost-btn delete-food" data-id="${x.id}">Delete</button></div></div>`).join('')}</div>`:'<div class="empty">No food logged today.</div>'}`;$('#add-food').onclick=()=>foodModal();$('#food-search-btn').onclick=foodSearchModal;$$('.delete-food').forEach(b=>b.onclick=async()=>{await api('/api/nutrition/'+b.dataset.id,{method:'DELETE'});renderNutrition()})}
function foodModal(pref={}){modal('Log food',`<form id="food-form" class="form-grid">${field('Food name','name',pref.name||'','','required')}${field('Serving','serving',pref.serving||'')}${field('Calories','calories',pref.calories||0,'number','min="0" step="0.1" required')}${field('Protein (g)','protein',pref.protein||0,'number','min="0" step="0.1"')}${field('Carbs (g)','carbs',pref.carbs||0,'number','min="0" step="0.1"')}${field('Fat (g)','fat',pref.fat||0,'number','min="0" step="0.1"')}<button class="primary-btn span-2">Add to today</button></form>`,'NUTRITION');$('#food-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/nutrition',{method:'POST',body:{...f,date:today(),calories:+f.calories,protein:+f.protein,carbs:+f.carbs,fat:+f.fat}});closeModal();renderNutrition()}catch(err){toast(err.message,true)}}}
async function foodSearchModal(){const foods=await api('/api/food-search?q=');modal('Food lookup',`<div class="stack"><div class="notice">Search by food name or barcode. Online lookup sends only the search term to Open Food Facts. Manual entry always remains available.</div><div class="button-row"><input class="field" id="food-query" placeholder="Chicken breast or barcode" style="flex:1;min-width:190px"><button class="primary-btn" id="lookup-food">Search</button><button class="outline-btn" id="scan-food">Scan barcode</button></div><div id="scanner-area" class="hidden scanner-area"><video id="scanner-video" playsinline muted></video><p class="muted">Hold the barcode steady inside the camera view. On unsupported devices, type the number above.</p></div><div id="food-lookup-result"><p class="eyebrow">BUILT-IN QUICK ADD</p><div class="list">${foods.map((x,i)=>`<button class="list-row pick-food" data-i="${i}"><div><strong>${esc(x.name)}</strong><small>${esc(x.serving)}</small></div><strong>${x.calories} kcal</strong></button>`).join('')}</div></div></div>`,'NUTRITION');const pick=()=>$$('.pick-food').forEach(b=>b.onclick=()=>foodModal(foods[+b.dataset.i]));pick();$('#lookup-food').onclick=async()=>{const q=$('#food-query').value.trim();if(!q)return;$('#food-lookup-result').innerHTML='<div class="empty">Searching…</div>';try{const f=await api('/api/food-lookup?q='+encodeURIComponent(q));foodModal(f)}catch(err){$('#food-lookup-result').innerHTML=`<div class="notice danger">${esc(err.message)}</div>`}};$('#food-query').onkeydown=e=>{if(e.key==='Enter'){$('#lookup-food').click()}};$('#scan-food').onclick=startBarcodeScanner}
function stopBarcodeScanner(){if(state.scanTimer){clearInterval(state.scanTimer);state.scanTimer=null}if(state.scanStream){state.scanStream.getTracks().forEach(t=>t.stop());state.scanStream=null}}
async function startBarcodeScanner(){const area=$('#scanner-area'),video=$('#scanner-video');if(!area||!video)return;area.classList.remove('hidden');if(!navigator.mediaDevices?.getUserMedia){toast('Camera access is not supported here. Enter the barcode manually.',true);return}try{state.scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});video.srcObject=state.scanStream;await video.play();if(!('BarcodeDetector'in window)){toast('Automatic barcode detection is unavailable. Enter the number manually.',true);return}const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e','code_128']});state.scanTimer=setInterval(async()=>{if(video.readyState<2)return;try{const codes=await detector.detect(video);if(codes.length){const value=codes[0].rawValue;stopBarcodeScanner();$('#food-query').value=value;$('#lookup-food').click()}}catch{}},400)}catch{toast('Camera permission was denied or no camera is available.',true)}}

async function renderProgress(){const xs=await api('/api/progress');$('#content').innerHTML=`<div class="section-head" style="margin-top:0"><h2>Body progress</h2><button class="primary-btn" id="log-progress">Log measurement</button></div>${xs.length?`<div class="grid grid-3"><div class="card stat"><div><span class="muted">Latest weight</span><strong>${xs[0].weightKg} kg</strong></div><span class="stat-icon">⚖</span></div><div class="card stat"><div><span class="muted">Change</span><strong>${(xs[0].weightKg-xs[xs.length-1].weightKg).toFixed(1)} kg</strong></div><span class="stat-icon">↗</span></div><div class="card stat"><div><span class="muted">Entries</span><strong>${xs.length}</strong></div><span class="stat-icon">▦</span></div></div><div class="section-head"><h2>History</h2></div><div class="table-wrap card"><table class="table"><thead><tr><th>Date</th><th>Weight</th><th>Body fat</th><th>Notes</th><th></th></tr></thead><tbody>${xs.map(x=>`<tr><td>${x.date}</td><td>${x.weightKg} kg</td><td>${x.bodyFat||'—'}</td><td>${esc(x.notes||'')}</td><td><button class="ghost-btn delete-progress" data-id="${x.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No progress entries yet.</div>'}`;$('#log-progress').onclick=()=>{modal('Log progress',`<form id="progress-form" class="form-grid">${field('Date','date',today(),'date','required')}${field('Weight (kg)','weightKg','','number','min="20" max="400" step="0.1" required')}${field('Body fat %','bodyFat','','number','min="1" max="80" step="0.1"')}<label class="field-wrap"><span>Notes</span><textarea class="textarea" name="notes"></textarea></label><button class="primary-btn span-2">Save</button></form>`);$('#progress-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/progress',{method:'POST',body:{...f,weightKg:+f.weightKg,bodyFat:+f.bodyFat||0}});closeModal();renderProgress()}catch(err){toast(err.message,true)}}};$$('.delete-progress').forEach(b=>b.onclick=async()=>{await api('/api/progress/'+b.dataset.id,{method:'DELETE'});renderProgress()})}

async function renderHabits(){const xs=await api('/api/habits?date='+today());$('#content').innerHTML=`<div class="section-head" style="margin-top:0"><h2>Today's habits</h2><button class="primary-btn" id="new-habit">Add habit</button></div><div class="grid grid-2">${xs.map(x=>`<button class="card list-row habit-toggle" data-id="${x.id}" data-done="${x.done}"><div style="display:flex;gap:12px;align-items:center"><span class="stat-icon">${esc(x.icon||'✓')}</span><div><strong>${esc(x.name)}</strong><small>${esc(x.category||'')}</small></div></div><span class="check ${x.done?'done':''}">${x.done?'✓':''}</span></button>`).join('')}</div>`;$('#new-habit').onclick=()=>{modal('Add habit',`<form id="habit-form" class="stack">${field('Habit name','name','','text','required')}${field('Icon or emoji','icon','✓')}${selectField('Category','category','Health',['Health','Training','Nutrition','Recovery','Mindset','Cardio'])}<button class="primary-btn">Add habit</button></form>`);$('#habit-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));await api('/api/habits',{method:'POST',body:f});closeModal();renderHabits()}};$$('.habit-toggle').forEach(b=>b.onclick=async()=>{await api('/api/habits/'+b.dataset.id+'/toggle',{method:'POST',body:{date:today(),done:b.dataset.done!=='true'}});renderHabits()})}

async function renderCheckin(){const xs=await api('/api/checkins');$('#content').innerHTML=`<div class="grid grid-2"><div class="card"><p class="eyebrow">30-SECOND REVIEW</p><h2>Adjust this week's plan</h2><form id="checkin-form" class="stack">${field('Sessions completed last week','lastWeekDays','3','number','min="0" max="7"')}${selectField('Energy','energy','solid',[{value:'crushed',label:'🔥 Feeling strong'},{value:'solid',label:'💪 Solid'},{value:'tired',label:'😴 A bit tired'},{value:'burnt',label:'😩 Burnt out'}])}<label class="field-wrap"><span>Days available this week</span><div class="button-row" id="day-picks">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<label class="tab-chip"><input type="checkbox" name="days" value="${d}"> ${d}</label>`).join('')}</div></label><label class="field-wrap"><span>Notes</span><textarea class="textarea" name="notes" placeholder="Bad knee, busy Friday, prefer mornings…"></textarea></label><button class="primary-btn">Complete check-in</button></form></div><div>${xs[0]?`<div class="card"><p class="eyebrow">LATEST RECOMMENDATION</p><h2>${esc(xs[0].date)}</h2><p style="white-space:pre-wrap;line-height:1.7">${esc(xs[0].recommendation)}</p></div>`:'<div class="empty">Your recommendation will appear here.</div>'}</div></div><div class="section-head"><h2>Check-in history</h2></div>${xs.length?`<div class="list">${xs.map(x=>`<div class="list-row"><div><strong>${x.date} · ${esc(x.energy)}</strong><small>${x.availableDays.join(', ')}</small></div><span class="pill">${x.lastWeekDays} last week</span></div>`).join('')}</div>`:'<div class="empty">No check-ins yet.</div>'}`;$('#checkin-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const days=f.getAll('days');try{await api('/api/checkins',{method:'POST',body:{date:today(),lastWeekDays:+f.get('lastWeekDays'),availableDays:days,energy:f.get('energy'),notes:f.get('notes')}});toast('Check-in complete.');renderCheckin()}catch(err){toast(err.message,true)}}}


async function renderMobile(){const info=await api('/api/system/mobile');const settings=state.user.role==='admin'?await api('/api/settings'):null;const urls=Array.isArray(info.urls)?info.urls:[];$('#content').innerHTML=`<div class="grid grid-2"><section class="card"><p class="eyebrow">INSTALLABLE PWA</p><h2>Use FormForge on your phone</h2><div class="notice ${info.enabled?'':'danger'}"><strong>${info.enabled?'Mobile access is enabled':'Mobile access is currently off'}</strong><br>${info.enabled?'Keep FormForge running on the Windows PC, then open one of the addresses below on the same Wi-Fi.':'An administrator must enable private-network access and restart the Windows app.'}</div><div class="list" style="margin-top:14px">${urls.map(u=>`<div class="list-row"><div><strong>${esc(u)}</strong><small>Private-network HTTPS address</small></div><button class="outline-btn copy-mobile-url" data-url="${esc(u)}">Copy</button></div>`).join('')||'<div class="empty">No private-network address was detected. Connect the PC to Wi-Fi or Ethernet and refresh.</div>'}</div><div class="stack" style="margin-top:14px"><a class="outline-btn" href="/api/system/ca" style="text-align:center;text-decoration:none">Download phone trust certificate</a><button class="outline-btn" id="mobile-install-help">Phone installation steps</button></div></section><section class="card"><p class="eyebrow">HOW IT WORKS</p><h2>Shared and offline modes</h2><div class="stack"><div class="list-row"><div><strong>Shared mobile app</strong><small>Workouts, logs, accounts, and online AI use the Windows server over your private network.</small></div><span class="pill">Same Wi-Fi</span></div><div class="list-row"><div><strong>Phone offline coach</strong><small>The installed PWA keeps a small rules-based coach and cached profile on the phone when the server is unavailable.</small></div><span class="pill">No internet</span></div><div class="list-row"><div><strong>Away from home</strong><small>Use a private VPN such as Tailscale or host FormForge securely. LAN addresses do not work over cellular by themselves.</small></div><span class="pill">VPN needed</span></div></div>${isLoopbackHost()?'<div class="notice" style="margin-top:14px">Do not install the desktop localhost page as a PWA. Use the real Windows desktop shortcut so the server starts first. Install the PWA from the phone’s LAN address instead.</div>':''}</section></div>${state.user.role==='admin'?`<section class="card" style="margin-top:16px"><p class="eyebrow">ADMINISTRATOR</p><h2>Mobile server controls</h2><form id="mobile-settings" class="form-grid">${selectField('Mobile/LAN access','lanEnabled',String(settings.lanEnabled),[{value:'false',label:'Off — this PC only'},{value:'true',label:'On — approved users on private network'}])}${field('HTTPS port','port',settings.port||8443,'number','min="1024" max="65535"')}${field('Backup copy folder','backupCopyPath',settings.backupCopyPath||'','text','placeholder="Optional"')}<div class="span-2 button-row"><button class="primary-btn">Save mobile settings</button><a class="outline-btn" href="formforge://restart" style="text-decoration:none;text-align:center">Restart and apply on Windows</a></div></form><div class="notice danger" style="margin-top:12px">The restart link works from the Windows desktop app. On a phone, close and reopen FormForge on the PC after saving.</div></section>`:''}`;$$('.copy-mobile-url').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.url);toast('Mobile address copied.')}catch{prompt('Copy this address:',b.dataset.url)}});$('#mobile-install-help').onclick=()=>modal('Install FormForge on a phone',`<ol class="mobile-steps"><li>On Windows, enable Mobile/LAN access and restart FormForge.</li><li>Run the included private-network firewall script as administrator if Windows blocks the connection.</li><li>On the phone, download and trust the FormForge local CA certificate.</li><li>Open one of the shown HTTPS addresses while on the same Wi-Fi.</li><li>Sign in with a separate approved account.</li><li>Choose Add to Home Screen or Install App in the phone browser.</li></ol><div class="notice">The Windows PC must remain on and FormForge must be running for shared records. The phone offline coach remains available from the installed PWA when the server cannot be reached.</div>`,'MOBILE SETUP');if(state.user.role==='admin'){$('#mobile-settings').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));await api('/api/settings',{method:'PUT',body:{lanEnabled:f.lanEnabled==='true',port:+f.port,backupCopyPath:f.backupCopyPath}});toast('Mobile settings saved. Restart FormForge on Windows to apply them.');renderMobile()}}}

async function renderAdmin(){if(state.user.role!=='admin'){state.page='dashboard';return renderPage()}const [users,audit]=await Promise.all([api('/api/admin/users'),api('/api/admin/audit?limit=100')]);$('#content').innerHTML=`<div class="section-head" style="margin-top:0"><h2>Authorized users</h2><button class="primary-btn" id="add-user">Add user</button></div><div class="table-wrap card"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${u.role}</td><td>${u.active?'Active':'Disabled'}</td><td>${u.id===state.user.id?'Current user':`<button class="ghost-btn edit-user" data-id="${u.id}">Edit</button>`}</td></tr>`).join('')}</tbody></table></div><div class="section-head"><h2>Audit log</h2></div><div class="table-wrap card"><table class="table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Target</th><th>IP</th></tr></thead><tbody>${audit.map(a=>`<tr><td>${new Date(a.at).toLocaleString()}</td><td>${esc(a.actorName||'System')}</td><td>${esc(a.action)}</td><td>${esc(a.target||'')}</td><td>${esc(a.ip||'')}</td></tr>`).join('')}</tbody></table></div>`;$('#add-user').onclick=()=>userModal();$$('.edit-user').forEach(b=>b.onclick=()=>userModal(users.find(u=>u.id===b.dataset.id)))}
function userModal(u=null){modal(u?'Edit user':'Add user',`<form id="user-form" class="stack">${field('Name','name',u?.name||'','','required')}${field('Email','email',u?.email||'','email','required')}${field(u?'New password (leave blank to keep)':'Temporary password','password','','password',u?'':'required minlength="12"')}${selectField('Role','role',u?.role||'user',['user','admin'])}${selectField('Plan tier','planTier',u?.planTier||'free',[{value:'free',label:'Free — offline only'},{value:'pro',label:'Pro — online AI'}])}${u?selectField('Status','active',String(u.active),[{value:'true',label:'Active'},{value:'false',label:'Disabled'}]):''}<button class="primary-btn">${u?'Save changes':'Create user'}</button>${u?'<button type="button" class="danger-btn" id="delete-user">Delete user and their data</button>':''}</form>`,'ACCESS');$('#user-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));if(u){f.active=f.active==='true';await api('/api/admin/users/'+u.id,{method:'PUT',body:f})}else await api('/api/admin/users',{method:'POST',body:{...f,profile:{name:f.name,goal:'General fitness',experience:'beginner',daysPerWeek:3,equipment:'Full gym'}}});closeModal();renderAdmin()};if(u)$('#delete-user').onclick=async()=>{if(!confirm('Delete this user and all of their fitness data?'))return;await api('/api/admin/users/'+u.id,{method:'DELETE'});closeModal();renderAdmin()}}

async function renderSettings(){const [profile,settings,backups]=await Promise.all([api('/api/profile'),state.user.role==='admin'?api('/api/settings'):Promise.resolve(null),state.user.role==='admin'?api('/api/backups'):Promise.resolve([])]);$('#content').innerHTML=`<div class="grid grid-2"><div class="card"><p class="eyebrow">PROFILE</p><h2>Fitness settings</h2><form id="profile-form" class="form-grid">${field('Name','name',profile.name||state.user.name,'text','required')}${field('Age','age',profile.age||'','number','min="13" max="120"')}${selectField('Gender','gender',profile.gender||'male',['male','female','other','prefer not to say'])}${field('Height (cm)','heightCm',profile.heightCm||'','number','step="0.1"')}${field('Weight (kg)','weightKg',profile.weightKg||'','number','step="0.1"')}${field('Goal weight (kg)','goalWeightKg',profile.goalWeightKg||'','number','step="0.1"')}${selectField('Goal','goal',profile.goal||'General fitness',['Build muscle','Lose fat','Improve endurance','Increase strength','General fitness'])}${selectField('Experience','experience',profile.experience||'beginner',['beginner','intermediate','advanced'])}${selectField('Days per week','daysPerWeek',profile.daysPerWeek||3,['2','3','4','5','6'])}${selectField('Equipment','equipment',profile.equipment||'Full gym',['Full gym','Home gym','Dumbbells only','Bodyweight only','Resistance bands'])}${field('Calorie goal','calorieGoal',profile.calorieGoal||'','number')}${field('Protein goal (g)','proteinGoal',profile.proteinGoal||'','number')}${field('Carb goal (g)','carbGoal',profile.carbGoal||'','number')}${field('Fat goal (g)','fatGoal',profile.fatGoal||'','number')}<button class="primary-btn span-2">Save profile</button></form></div><div class="card"><p class="eyebrow">DATA</p><h2>Export and import</h2><div class="stack"><button class="outline-btn" id="export-json">Export my data (JSON)</button><button class="outline-btn" id="export-nutrition">Export nutrition CSV</button><button class="outline-btn" id="export-progress">Export progress CSV</button><button class="outline-btn" id="export-workouts">Export workouts CSV</button><label class="outline-btn" style="text-align:center">Import FormForge JSON<input id="import-json" type="file" accept="application/json" hidden></label></div></div></div>${state.user.role==='admin'?`<div class="grid grid-2" style="margin-top:16px"><div class="card"><p class="eyebrow">NETWORK</p><h2>Private-network access</h2><form id="system-form" class="stack">${selectField('LAN access','lanEnabled',String(settings.lanEnabled),[{value:'false',label:'Off — this PC only'},{value:'true',label:'On — private network users'}])}${field('HTTPS port','port',settings.port||8443,'number','min="1024" max="65535"')}${field('Backup copy folder','backupCopyPath',settings.backupCopyPath||'','text','placeholder="Optional OneDrive or selected folder path"')}<button class="primary-btn">Save system settings</button><div class="notice">Restart FormForge after changing network or port settings. LAN access also requires a private-profile Windows Firewall rule and trusting the local CA on each phone or tablet.</div><a href="/api/system/ca">Download local CA certificate</a></form></div><div class="card"><p class="eyebrow">RECOVERY</p><h2>Encrypted backups</h2><div class="button-row"><button class="primary-btn" id="backup-now">Back up now</button><button class="outline-btn" id="recovery-key">Export recovery key</button></div><label class="outline-btn" style="display:block;text-align:center;margin-top:10px">Restore encrypted backup<input id="restore-backup" type="file" accept=".ffbackup" hidden></label><div class="list" style="margin-top:14px">${backups.map(b=>`<div class="list-row"><div><strong>${esc(b.name)}</strong><small>${new Date(b.modifiedAt).toLocaleString()} · ${Math.round(b.size/1024)} KB</small></div><a class="outline-btn" href="/api/backups/download?name=${encodeURIComponent(b.name)}">Download</a></div>`).join('')||'<div class="empty">No backups yet.</div>'}</div></div></div>`:''}`;$('#profile-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));for(const k of ['age','heightCm','weightKg','goalWeightKg','daysPerWeek','calorieGoal','proteinGoal','carbGoal','fatGoal'])f[k]=+f[k]||0;await api('/api/profile',{method:'PUT',body:f});toast('Profile saved.');state.user.name=f.name;$('#user-chip').textContent=`${state.user.name} · ${state.user.role}`};$('#export-json').onclick=()=>downloadURL('/api/export/json');$('#export-nutrition').onclick=()=>downloadURL('/api/export/csv?type=nutrition');$('#export-progress').onclick=()=>downloadURL('/api/export/csv?type=progress');$('#export-workouts').onclick=()=>downloadURL('/api/export/csv?type=workouts');$('#import-json').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());await api('/api/import/json',{method:'POST',body:{data}});toast('Data imported.')}catch(err){toast(err.message,true)}};if(state.user.role==='admin'){ $('#system-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));await api('/api/settings',{method:'PUT',body:{lanEnabled:f.lanEnabled==='true',port:+f.port,backupCopyPath:f.backupCopyPath}});toast('Settings saved. Restart FormForge to apply network changes.')};$('#backup-now').onclick=async()=>{try{await api('/api/backups',{method:'POST',body:{}});toast('Encrypted backup created.');renderSettings()}catch(e){toast(e.message,true)}};$('#recovery-key').onclick=()=>downloadURL('/api/recovery-key');$('#restore-backup').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!confirm('Restore this backup? Current data will first be backed up, and all users will be signed out.'))return;const recoveryKey=prompt('Recovery key (leave blank for backups from this installation):','')||'';const data=await fileToBase64(file);try{const r=await api('/api/backups/restore',{method:'POST',body:{data,recoveryKey}});alert(r.message);location.reload()}catch(err){toast(err.message,true)}}}}
function downloadURL(url){const a=document.createElement('a');a.href=url;a.click()}
function downloadText(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function fileToBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file)})}
boot().catch(renderStartupFailure);
